/// <summary>
/// the <C>METSysOperationServiceController</C> base class for sys  controller, extended to get custom data contract
/// </summary>
public class METSysOperationServiceController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
/// method to get data contract object based on attribute value.
/// </summary>
/// <param name = "_dictMethod">calling method</param>
/// <param name = "_parameterIndex">index value</param>
/// <returns>data contract object</returns>
protected Object initializeServiceParameter(DictMethod _dictMethod, int _parameterIndex)
{
    SysDictClass                                dataContractClass;
    Object                                      dataContractObject = null;
    METSysOperationDataContractNameAttribute    dataContractName   = _dictMethod.getAttribute(classStr(METSysOperationDataContractNameAttribute));

    if (dataContractName.parmDataContractName() == '')
    {
        super(_dictMethod,_parameterIndex);
    }
    else
    {
        if (_dictMethod.parameterType(_parameterIndex) == Types::Class)
        {
            dataContractClass = new SysDictClass(className2Id(dataContractName.parmDataContractName()));
            dataContractObject = dataContractClass.makeObject();
        }
    }
    return dataContractObject;
}

/// <summary>
/// triggering method for controller class
/// </summary>
/// <param name = "_args">args record from the caller</param>
public static void main(Args _args)
{
    METSysOperationServiceController controller;

    controller = new METSysOperationServiceController();
    controller.initializeFromArgs(_args);
    controller.startOperation();
}
